RevealOverworldSecret:
|1BC8A4| STX.b $04

|1BC8A6| LDA.w $0B9C
|1BC8A9| AND.w #$FF00
|1BC8AC| STA.w $0B9C

|1BC8AF| LDA.b $8A
|1BC8B1| CMP.w #$0080 ; SPOW
|1BC8B4| BCS .fail

|1BC8B6| ASL A
|1BC8B7| TAX

|1BC8B8| LDA.l OverworldData_HiddenItems,X
|1BC8BC| STA.b $00

|1BC8BE| LDA.w #^OverworldData_HiddenItems
|1BC8C1| STA.b $02

|1BC8C3| LDY.w #-3

.next_check
|1BC8C6| INY
|1BC8C7| INY
|1BC8C8| INY

|1BC8C9| LDA.b [$00],Y

|1BC8CB| CMP.w #$FFFF
|1BC8CE| BEQ .fail

|1BC8D0| AND.w #$7FFF
|1BC8D3| CMP.b $04
|1BC8D5| BNE .next_check

|1BC8D7| INY
|1BC8D8| INY

|1BC8D9| LDA.b [$00],Y
|1BC8DB| AND.w #$00FF
|1BC8DE| BEQ .dont_set_secret_id

|1BC8E0| CMP.w #$0080
|1BC8E3| BCS .dont_set_secret_id

|1BC8E5| TSB.w $0B9C

.dont_set_secret_id
|1BC8E8| AND.w #$00FF
|1BC8EB| CMP.w #$0080
|1BC8EE| BCC .item_secret

|1BC8F0| PHA

|1BC8F1| LDA.w $0B9C
|1BC8F4| ORA.w #$00FF
|1BC8F7| STA.w $0B9C

|1BC8FA| PLA
|1BC8FB| CMP.w #$0084
|1BC8FE| BEQ .not_stairs

|1BC900| LDX.b $8A
|1BC902| LDA.l $7EF280,X
|1BC906| AND.w #$0002
|1BC909| BNE .not_stairs

|1BC90B| LDA.b $8A
|1BC90D| CMP.w #$005B ; OW 5B
|1BC910| BNE .not_pyramid_screen

|1BC912| LDA.l $7EF3CC
|1BC916| AND.w #$00FF
|1BC919| CMP.w #$0D ; FOLLOWER 0D
|1BC91C| BNE .fail

.not_pyramid_screen
|1BC91E| SEP #$20

|1BC920| LDA.b #$1B ; SFX3.1B
|1BC922| STA.w $012F

|1BC925| REP #$20

.not_stairs
|1BC927| LDA.b [$00],Y
|1BC929| AND.w #$000F
|1BC92C| TAX

|1BC92D| LDA.l SecretObjectTypes,X
|1BC931| STA.b $0E

.fail
|1BC933| JSR AdjustSecretForPowder
|1BC936| LDX.b $04

|1BC938| CLC

|1BC939| RTS

.item_secret
|1BC93A| JSR AdjustSecretForPowder
|1BC93D| LDX.b $04
|1BC93F| LDA.b $0E

|1BC941| SEC

|1BC942| RTS

;===================================================================================================

AdjustSecretForPowder:
|1BC943| LDA.w $0301
|1BC946| AND.w #$0040
